function isPrime(number) {
return new Promise((resolve, reject) =>
{
if (number <= 1) {
reject('$ {number} não é primo');
} else {
for (let i = 2; i <=
Math.sqrt(number); i++) {
if (number % i === “0”) {
reject('$ {number} não é primo');
}
}
resolve('$ {number} é primo');
}
});
}
